package com.arcadiadevs.viora.platform.orchard.interfaces.rest.resources;

import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.LocalDate;

/**
 * Request to write a field note.
 *
 * @param id         identity generated by the phone
 * @param type       what it is about
 * @param text       free text
 * @param observedOn day it refers to
 */
@Schema(name = "RecordFieldNoteResource", description = "Field note written by the producer in the logbook (P75)")
public record RecordFieldNoteResource(
        @NotBlank @Schema(description = "UUID generated by the phone; resending it does not duplicate the note",
                example = "6f1c2a0e-3b8d-4a51-9c3e-2d7f8b9a1c45") String id,
        @NotBlank @Schema(description = "IRRIGATION, PRUNING, FERTILIZATION, PESTS or OTHER", example = "IRRIGATION")
        String type,
        @NotBlank @Schema(description = "Free text, up to 500 characters",
                example = "Adelanté el riego a la tarde por el calor. Revisar goteros de la fila 4.") String text,
        @NotNull @Schema(description = "Day the note refers to, not in the future", example = "2026-11-18")
        LocalDate observedOn) {
}
